import org.springframework.beans.factory.*;
import org.springframework.context.annotation.*;

interface Notifier {
    String send(String message);
}

class ConsoleNotifier implements Notifier {   // 既定の部品
    public String send(String m) { return "[CONSOLE] " + m; }
}

class SlackNotifier implements Notifier {     // 利用者が用意する部品
    public String send(String m) { return "[SLACK #ops] " + m; }
}

// 「自動設定」のつもり:利用者が Notifier を定義していれば、それを使う。
// 無ければ既定の ConsoleNotifier で動く(@ConditionalOnMissingBean の考え方)
@Configuration
class AlertAutoConfig {
    @Bean
    AlertService alertService(ObjectProvider<Notifier> notifiers) {
        Notifier n = notifiers.getIfAvailable(() -> {
            System.out.println("(Notifier が無いので既定の ConsoleNotifier を使います)");
            return new ConsoleNotifier();
        });
        return new AlertService(n);
    }
}

// 利用者の設定(アプリ側で書くもの)
@Configuration
class UserConfig {
    @Bean
    Notifier slackNotifier() {
        return new SlackNotifier();
    }
}

record AlertService(Notifier notifier) {
    void alert(String msg) { System.out.println(notifier.send(msg)); }
}

System.out.println("--- 利用者の設定なし ---");
try (var ctx = new AnnotationConfigApplicationContext(AlertAutoConfig.class)) {
    ctx.getBean(AlertService.class).alert("ディスク残量 5%");
}

System.out.println("--- 利用者が Notifier を定義した ---");
// ここを変えてみよう:UserConfig の slackNotifier を消したり、別の Notifier を返したりする
try (var ctx = new AnnotationConfigApplicationContext(
        UserConfig.class, AlertAutoConfig.class)) {
    ctx.getBean(AlertService.class).alert("ディスク残量 5%");
}

import org.springframework.util.ClassUtils;

// @ConditionalOnClass の考え方:「その jar(クラス)がクラスパスにあるか」で設定を使うか決める
// この実行環境には Spring・Jackson・Tomcat の jar は入っているが、Thymeleaf と MySQL ドライバは入っていない
record AutoConfig(String name, String requiredClass) { }

// ここを変えてみよう:自分で思いつくクラス名(java.time.LocalDate など)を足してみる
List<AutoConfig> candidates = List.of(
        new AutoConfig("JacksonAutoConfiguration",
                "com.fasterxml.jackson.databind.ObjectMapper"),
        new AutoConfig("WebMvcAutoConfiguration",
                "org.springframework.web.servlet.DispatcherServlet"),
        new AutoConfig("EmbeddedTomcat",
                "org.apache.catalina.startup.Tomcat"),
        new AutoConfig("ThymeleafAutoConfiguration",
                "org.thymeleaf.spring6.SpringTemplateEngine"),
        new AutoConfig("DataSourceAutoConfiguration(MySQL)",
                "com.mysql.cj.jdbc.Driver"));

List<String> positive = new ArrayList<>();
List<String> negative = new ArrayList<>();
for (AutoConfig c : candidates) {
    boolean present = ClassUtils.isPresent(c.requiredClass(), null);
    String simple = c.requiredClass().substring(c.requiredClass().lastIndexOf('.') + 1);
    if (present) {
        positive.add(c.name() + " matched:\n      - found required class '" + simple + "'");
    } else {
        negative.add(c.name() + ":\n      - did not find required class '" + simple + "'");
    }
}
System.out.println("=== 自動設定レポートもどき ===");
System.out.println("Positive matches:");
positive.forEach(s -> System.out.println("   " + s));
System.out.println("Negative matches:");
negative.forEach(s -> System.out.println("   " + s));

